import XCTest

/// Boxes on a page shown turned, as a person sees them: the bundled
/// `--turnedDoc` fixture (UITestFixtures/uitest_turned.pdf, generated by
/// Scripts/generate_uitest_turned.py) is one Letter page stored upright and
/// shown turned a quarter, with one word, "Marigold", running down its
/// right side.
///
/// Canvas regions are not in the accessibility tree, so both cases read
/// the screen: the word is found by its own black ink in a screenshot
/// taken before any box, and a box by its page-teal line (every box, drawn
/// or placed by Search) in one taken after. Nothing here maps a point into
/// the page: the drag is pressed at the ink's corners, and every reading
/// is in window points.
///
/// nonisolated for the same reason as the sibling suites: an XCUITest
/// drives a separate process and touches no @MainActor app state.
nonisolated final class TurnedPageBoxUITests: XCTestCase {

    private var app: XCUIApplication!

    override func setUp() {
        super.setUp()
        continueAfterFailure = false
        app = XCUIApplication()
    }

    override func tearDown() {
        app = nil
        super.tearDown()
    }

    private var window: XCUIElement { app.windows.firstMatch }

    /// The page on screen, in window points, as `wordInk()` read it; box
    /// tints are read inside it alone, clear of the toolbar and messages.
    private var page = CGRect.null

    // MARK: - Tests

    /// A box drawn with Rectangle over the word on the turned page is
    /// drawn over the word.
    func testABoxDrawnOverTheWordIsDrawnOverIt() throws {
        launchTurnedPage()
        let word = try wordInk()
        enterDrawMode()
        let start = point(CGPoint(x: word.minX - 8, y: word.minY - 8))
        let end = point(CGPoint(x: word.maxX + 8, y: word.maxY + 8))
        start.press(forDuration: 0.05, thenDragTo: end, withVelocity: .slow, thenHoldForDuration: 0.2)
        let page = self.page
        let box = try XCTUnwrap(waitForTint(within: 10) { $0.tintBounds(.teal, in: page) },
                                "the drawn box is on screen")
        attachScreenshot(named: "turned-page-drawn-box")
        XCTAssertGreaterThan(share(of: word, inside: box), 0.95,
                             "The drawn box sits at \(box); the word is at \(word).")
    }

    /// The box Search places on the word on the turned page is drawn over
    /// the word.
    func testTheBoxSearchPlacesIsDrawnOverTheWord() throws {
        launchTurnedPage()
        let word = try wordInk()
        app.buttons["searchRedact"].tap()
        let field = app.textFields["Search text"]
        XCTAssertTrue(field.waitForExistence(timeout: 15), "the Search sheet opened")
        field.tap()
        field.typeText("Marigold")
        let selectAll = app.buttons["Select All"]
        XCTAssertTrue(selectAll.waitForExistence(timeout: 15), "Search found the word")
        selectAll.tap()
        let apply = app.buttons["searchApplyButton"]
        XCTAssertTrue(apply.waitForExistence(timeout: 5) && apply.isEnabled, "Apply is enabled")
        apply.tap()
        let marked = app.staticTexts.matching(NSPredicate(format: #"label BEGINSWITH "Marked""#)).firstMatch
        XCTAssertTrue(marked.waitForExistence(timeout: 15), "the apply placed the box")
        let dismiss = app.buttons["searchDismissButton"].firstMatch
        XCTAssertTrue(dismiss.waitForExistence(timeout: 10), "the sheet can be closed")
        dismiss.tap()
        XCTAssertTrue(dismiss.waitForNonExistence(timeout: 10), "the sheet closed")
        let page = self.page
        let box = try XCTUnwrap(waitForTint(within: 10) { $0.tintBounds(.teal, in: page) },
                                "the Search box is on screen")
        attachScreenshot(named: "turned-page-search-box")
        XCTAssertGreaterThan(share(of: word, inside: box), 0.95,
                             "The Search box sits at \(box); the word is at \(word).")
    }

    // MARK: - Launch

    private func launchTurnedPage() {
        app.launchArguments = ["--uitesting", "--loadTestDocument", "--turnedDoc"]
        app.launch()
        XCTAssertTrue(app.buttons["drawTool"].waitForExistence(timeout: 30),
                      "The editor never opened the turned fixture — check the --turnedDoc launch hook.")
        sleep(1)
    }

    // MARK: - Reading the screen

    private func probe() throws -> CanvasPixelProbe {
        try XCTUnwrap(CanvasPixelProbe(XCUIScreen.main.screenshot(), windowSize: window.frame.size),
                      "a screenshot was read")
    }

    /// The word's black ink on the page, in window points: the page is the
    /// longest white run down x = 12 and across its middle row (kept in
    /// `page`), and the ink is every dark point inside it.
    private func wordInk() throws -> CGRect {
        let shot = try probe()
        let size = window.frame.size
        func white(_ x: CGFloat, _ y: CGFloat) -> Bool {
            let (r, g, b) = shot.rgb(x, y)
            return r >= 250 && g >= 250 && b >= 250
        }
        func longestRun(_ count: Int, _ isWhite: (Int) -> Bool) -> (Int, Int)? {
            var best: (Int, Int)?
            var start: Int?
            for i in 0...count {
                let w = i < count && isWhite(i)
                if w, start == nil { start = i }
                if !w, let s0 = start {
                    if best == nil || (i - s0) > (best!.1 - best!.0) { best = (s0, i) }
                    start = nil
                }
            }
            return best
        }
        let column = try XCTUnwrap(longestRun(Int(size.height)) { white(12, CGFloat($0)) }, "the page is on screen")
        let midY = CGFloat(column.0 + column.1) / 2
        let row = try XCTUnwrap(longestRun(Int(size.width)) { white(CGFloat($0), midY) }, "the page is on screen")
        let page = CGRect(x: CGFloat(row.0), y: CGFloat(column.0),
                          width: CGFloat(row.1 - row.0), height: CGFloat(column.1 - column.0)).insetBy(dx: 2, dy: 2)
        XCTAssertGreaterThan(page.width, page.height, "the turned page is shown wider than tall")
        self.page = page
        var minX = CGFloat.infinity, minY = CGFloat.infinity, maxX = -CGFloat.infinity, maxY = -CGFloat.infinity
        var y = page.minY
        while y < page.maxY {
            var x = page.minX
            while x < page.maxX {
                let (r, g, b) = shot.rgb(x, y)
                if r < 90 && g < 90 && b < 90 {
                    minX = min(minX, x); minY = min(minY, y); maxX = max(maxX, x); maxY = max(maxY, y)
                }
                x += 1
            }
            y += 1
        }
        XCTAssertTrue(maxX > minX, "the word's ink is on the page")
        let word = CGRect(x: minX, y: minY, width: maxX - minX + 1, height: maxY - minY + 1)
        XCTAssertGreaterThan(word.height, word.width, "the word runs down the turned page")
        return word
    }

    private func share(of target: CGRect, inside box: CGRect) -> CGFloat {
        let overlap = box.intersection(target)
        return overlap.isNull ? 0 : (overlap.width * overlap.height) / (target.width * target.height)
    }

    private func point(_ p: CGPoint) -> XCUICoordinate {
        window.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(dx: p.x, dy: p.y))
    }

    // MARK: - Tool and page bar

    private func enterDrawMode() {
        let tool = app.buttons["drawTool"]
        XCTAssertTrue(tool.waitForExistence(timeout: 10), "Rectangle tool not present.")
        for _ in 0..<3 {
            tool.tap()
            let deadline = Date().addingTimeInterval(6)
            while Date() < deadline {
                if tool.drawToolReads("Drawing mode active") { return }
                usleep(250_000)
            }
        }
        XCTFail("The Rectangle tool did not report drawing mode after three taps.")
    }

    /// Reads the screen until `read` returns a box, then once more a second
    /// later so a box still settling is read where it rests.
    private func waitForTint(within timeout: TimeInterval, _ read: (CanvasPixelProbe) -> CGRect?) -> CGRect? {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if let shot = try? probe(), read(shot) != nil {
                sleep(1)
                return (try? probe()).flatMap(read)
            }
            usleep(500_000)
        }
        return nil
    }
}
